(function () {
  'use strict';
  const chunkSet = {"title":"Text Evidence","topic":"Reading Comprehension","questions":[{"id":"reading-comprehension-text-evidence-q0151","version":3,"contentHash":"sha256:3f6e5fde2c62bea6423105d985c5725a16f99541e2e553fda46e6a3cd0d419f7","question":"Read the passage. Grade 5 developing passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. These details show that students used careful daily routines to help a garden grow.\n\nWhich sentence from the passage best supports this idea: The students used observations to care for the plants.","choices":["The title names the topic but gives no proof.","The art room displayed clay bowls near the window.","The passage says every reader already knew about school garden.","They recorded how tall the seedlings grew."],"correct":3,"studyAid":{"definition":"To support an idea, find evidence that specifically matches the action or claim mentioned in the prompt.","example":"Idea: The puppy was energetic. Evidence: The puppy chased its tail and ran around the yard for an hour.","strategyClue":"Highlight the key words in the prompt, such as 'observations' or 'tracking,' and then scan the passage for a sentence that describes a direct action linked to those words.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They recorded how tall the seedlings grew. This sentence directly describes students measuring and tracking the plants' progress, which is a specific form of observation used to ensure the garden's health.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"This is a general statement about how a text is structured, not a specific action performed by the students that shows they observed the plants."},{"choice":"The art room displayed clay bowls near the window.","category":"off-topic sentence","reason":"This sentence describes items in an art room and mentions nothing about the garden or the students' work with plants."},{"choice":"The passage says every reader already knew about school garden.","category":"unsupported claim","reason":"This statement makes an assumption about the reader's knowledge rather than providing evidence of the students' hands-on work with the seedlings."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":151,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0152","version":3,"contentHash":"sha256:eb4d6b37953b8f6e82b3e0c7428b57713e19cb8c8dff821647faabbaafd71a79","question":"Read the passage. Grade 5 developing passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. These details show that student volunteers organized books and labels to make the library easier to use.\n\nWhich detail is the strongest evidence for the answer, \"The volunteers helped readers find materials more efficiently.\"?","choices":["They sorted returned books by call number before placing them on shelves.","The cafeteria served tomato soup on Thursday.","The passage says every reader already knew about library helpers.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports your claim or answer.","example":"Claim: The garden was well-cared for. Evidence: 'The students watered the flowers every single morning.'","strategyClue":"Look for a sentence in the text that describes an action related to the keyword 'find' or 'materials.' Eliminate choices that mention things not discussed in the passage.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This is the strongest evidence because call numbers are specifically used to organize books systematically, which directly helps readers find the exact materials they need quickly and efficiently.","incorrect":["",{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This sentence is about food, not library organization. Evidence must directly relate to the library and the specific task of helping readers find materials."},{"choice":"The passage says every reader already knew about library helpers.","category":"not supported by text","reason":"The text never makes this claim. Even if it were true, it does not explain how materials became easier to find or more efficient to locate."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title might introduce a subject, but it does not provide the specific actions or 'details' needed to prove how the volunteers improved library efficiency."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":152,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0153","version":3,"contentHash":"sha256:bc5c90e12ee3285ef0eaed0a7d239942e2d5aad292aea47749be614ccea6fe8f","question":"Read the passage. Grade 5 developing passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. These details show that a science club collected and reused rainwater to care for plants.\n\nWhich sentence from the passage best supports this idea: The rain barrel reduced the need for hose water.","choices":["A soccer team practiced corner kicks after school.","Members used the stored water on dry afternoons instead of turning on the hose.","The passage says every reader already knew about rain barrel.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting details are the facts, examples, or specific actions found in a text that prove the main idea is true.","example":"Main Idea: Pets are helpful. Supporting Detail: My dog barks when someone is at the door, helping us feel safe.","strategyClue":"Ask yourself: 'Which sentence describes an action or fact that proves the club actually reused the water?' Look for the sentence that connects the club's behavior directly to the goal of saving water.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Members used the stored water on dry afternoons instead of turning on the hose. This sentence directly describes the action of replacing tap water (the hose) with collected rainwater, which provides the evidence needed to support the idea that the club reused water to care for plants.","incorrect":[{"choice":"A soccer team practiced corner kicks after school.","category":"irrelevant information","reason":"This sentence is about soccer and has nothing to do with rainwater or the science club's project. It does not support the idea at all."},"",{"choice":"The passage says every reader already knew about rain barrel.","category":"incorrect claim","reason":"The passage never makes this statement. Evidence for a claim must come from facts stated in the text, not from guesses about what readers know."},{"choice":"The title names the topic but gives no proof.","category":"inaccurate evidence","reason":"While a title might name a topic, it does not provide the specific actions or details needed to 'support' an idea. This choice describes the title rather than providing evidence for the club's actions."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":153,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0154","version":3,"contentHash":"sha256:d3c0b39c02bd8a211f04098049b2a6b059f198bebd57ab7b2858844baba18d40","question":"Read the passage. Grade 5 developing passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. These details show that student reporters gathered facts and published school news.\n\nWhich detail is the strongest evidence for the answer, \"The reporters tried to make the newspaper accurate.\"?","choices":["The passage says every reader already knew about class newspaper.","The playground slide was painted blue over spring break.","They interviewed teachers, wrote short articles, and checked facts before printing.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Strong evidence is a specific piece of information from a text that directly supports a claim or answers a question.","example":"Claim: The garden is healthy. Evidence: The flowers are blooming and the leaves are green.","strategyClue":"Identify the key action verb in the claim (e.g., 'tried to make accurate') and scan the text for a specific step or behavior that proves that exact action happened.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They interviewed teachers, wrote short articles, and checked facts before printing. Checking facts is the direct definition of trying to ensure accuracy, making this the strongest evidence for the claim.","incorrect":[{"choice":"The passage says every reader already knew about class newspaper.","category":"Unsupported passage claim","reason":"This statement is not found in the text and does not explain how the writers ensured accuracy."},{"choice":"The playground slide was painted blue over spring break.","category":"Irrelevant story detail","reason":"This detail is unrelated to the process of creating a newspaper or the goal of reporting information accurately."},"",{"choice":"The title names the topic but gives no proof.","category":"Generic structural observation","reason":"While titles identify topics, they do not provide evidence of a reporter's actions or their commitment to factual truth."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":154,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0155","version":3,"contentHash":"sha256:b9ef2fd1c00f13e74b01c22efc2cb7b07f4987133e8e536fec240ed8de7adaf9","question":"Read the passage. Grade 5 developing passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. These details show that families cleaned litter from the beach and encouraged visitors to keep it clean.\n\nWhich sentence from the passage best supports this idea: The cleanup made the beach safer for wildlife.","choices":["The title names the topic but gives no proof.","The town band played a concert in the park.","The passage says every reader already knew about beach cleanup.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line."],"correct":3,"studyAid":{"definition":"To support a claim, you must identify a piece of text that acts as 'proof' or 'evidence' for that specific idea.","example":"Claim: 'The rainstorm was strong.' Evidence: 'The overflowing gutters flooded the entire sidewalk.'","strategyClue":"Highlight the keywords in the claim (like 'safer' or 'wildlife') and then scan the passage for a sentence that lists specific actions taken to address those exact topics.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides specific, measurable evidence that trash—which is dangerous to wildlife—was successfully removed from the beach environment.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"The title usually introduces a subject, but it does not provide the concrete evidence needed to prove that specific action, like making a beach safer, actually took place."},{"choice":"The town band played a concert in the park.","category":"off-topic information","reason":"This sentence describes an event in a park, which is unrelated to the beach cleanup or wildlife safety mentioned in the passage."},{"choice":"The passage says every reader already knew about beach cleanup.","category":"unsupported assumption","reason":"The passage does not state what the reader knows; it provides facts about the volunteers' actions to support the idea that the beach was cleaned."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":155,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0156","version":3,"contentHash":"sha256:2d7cdabd67918cfb868d2032c77ab2cc5a75b3e659d806904028df76b7239463","question":"Read the passage. Grade 5 developing passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. These details show that a safety officer taught students important bike safety habits.\n\nWhich detail is the strongest evidence for the answer, \"A helmet must fit correctly to protect a rider.\"?","choices":["She showed how helmets should sit flat and snug on a rider's head.","The school choir rehearsed a song about the moon.","The passage says every reader already knew about bike safety.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Strong evidence is a specific sentence from the text that directly explains or proves the point being made.","example":"Point: Dogs need exercise. Evidence: 'The owner took the dog for a long run every morning.'","strategyClue":"Look for the answer choice that repeats key words from the claim, such as 'helmet' or 'fit', and explains the 'how' behind the rule.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She showed how helmets should sit flat and snug on a rider's head. This sentence provides specific instructions on the physical fit of a helmet, which directly supports the claim that a helmet must fit correctly to provide safety.","incorrect":["",{"choice":"The school choir rehearsed a song about the moon.","category":"irrelevant information","reason":"This sentence is not in the passage and has no connection to bike safety or how to wear a helmet correctly."},{"choice":"The passage says every reader already knew about bike safety.","category":"unsupported claim","reason":"The passage never states that readers already know about bike safety; this choice makes a claim that is not found in the text."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"A title might introduce a topic, but it does not provide the specific instructional details needed to prove how a helmet should fit."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":156,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0157","version":3,"contentHash":"sha256:d679365ed1229c260ba335ec1fe9a0d3fa86cdf5c1185de515a0ff935a895dbe","question":"Read the passage. Grade 5 developing passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. These details show that transportation planners improved bus service so people could reach useful places.\n\nWhich sentence from the passage best supports this idea: The new bus route served community needs.","choices":["A bakery sold cinnamon rolls before sunrise.","The new route stopped near the clinic, grocery store, and community center.","The passage says every reader already knew about city buses.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting evidence consists of specific facts or details from the text that explain why a main idea or claim is true.","example":"Claim: The park is fun. Evidence: The park has a tall slide and a grassy area for soccer.","strategyClue":"Look for the sentence that connects the topic of 'bus routes' to real-world locations that people in a neighborhood actually use.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The new route stopped near the clinic, grocery store, and community center. This sentence lists specific locations that provide essential services to the public, which directly supports the claim that the bus route serves community needs.","incorrect":[{"choice":"A bakery sold cinnamon rolls before sunrise.","category":"irrelevant information","reason":"While this sentence describes a business, it does not mention bus routes or public transportation, so it does not support the idea of serving community transit needs."},"",{"choice":"The passage says every reader already knew about city buses.","category":"unsupported claim","reason":"This information is not found in the text and does not provide any evidence about how the bus routes help the community."},{"choice":"The title names the topic but gives no proof.","category":"not textual evidence","reason":"A title is just a label and cannot act as evidence or proof for the claim made about the bus route's purpose."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":157,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0158","version":3,"contentHash":"sha256:d5a06c7fedb6f780588db299056e38148f42b06f4d62d2a49332446732626e95","question":"Read the passage. Grade 5 developing passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. These details show that actors and crew members cooperated to get a play ready.\n\nWhich detail is the strongest evidence for the answer, \"The production required more than acting.\"?","choices":["The passage says every reader already knew about school play.","A math poster showed different kinds of triangles.","Actors practiced lines while stage crew members painted scenery and tested lights.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports or proves a main idea.","example":"Main idea: Dogs are helpful. Evidence: Dogs help people cross the street and find lost items.","strategyClue":"Look for the sentence that describes specific tasks being performed by different people, as these tasks demonstrate the 'requirements' needed to reach the goal.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence provides direct evidence of work being done by two different groups, showing that a production involves more than just acting.","incorrect":[{"choice":"The passage says every reader already knew about school play.","category":"irrelevant information","reason":"The knowledge of the reader does not explain the physical tasks required to put on a play."},{"choice":"A math poster showed different kinds of triangles.","category":"unrelated detail","reason":"This detail is completely unrelated to the production of a play or the work involved in theater."},"",{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"While a title identifies the topic, it does not describe the specific actions or labor needed to support the claim about production requirements."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":158,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0159","version":3,"contentHash":"sha256:6bb9503c0067d371931e5cc8857606072256b4f27a586a3cbc6bcfbeb8840310","question":"Read the passage. Grade 5 developing passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. These details show that cafeteria food scraps were collected and turned into compost for flowers.\n\nWhich sentence from the passage best supports this idea: Food scraps can become useful instead of being thrown away.","choices":["The title names the topic but gives no proof.","A new scoreboard was installed in the gym.","The passage says every reader already knew about compost bin.","After several weeks, the dark compost was mixed into flower beds."],"correct":3,"studyAid":{"definition":"Supporting evidence consists of specific facts or actions mentioned in the text that directly relate to the main idea or claim.","example":"Claim: The classroom was messy. Evidence: Papers were scattered on the floor and the desks were covered in markers.","strategyClue":"Look for a sentence that describes an action or result showing how the waste item was turned into something new. Discard choices that are opinions, unrelated to the topic, or summaries not found in the text.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After several weeks, the dark compost was mixed into flower beds. This sentence shows the food scraps being transformed from waste into something useful for the flowers, directly supporting the idea that food scraps can have a new purpose.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"missing textual evidence","reason":"This is a statement about a title rather than a sentence from the passage that proves the food scraps were used for a purpose."},{"choice":"A new scoreboard was installed in the gym.","category":"irrelevant information","reason":"This sentence describes an event at the gym, which has nothing to do with the cafeteria food scraps or the composting process."},{"choice":"The passage says every reader already knew about compost bin.","category":"unsupported claim","reason":"The passage does not state that readers already know about the bins; this choice incorrectly summarizes reader knowledge rather than providing evidence from the text."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":159,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0160","version":3,"contentHash":"sha256:82fda53f686b135f8a45b365c2251c033bb0f96e7d950de1377fcb3622b2cf46","question":"Read the passage. Grade 5 developing passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. These details show that science students recorded weather measurements and used them to find patterns.\n\nWhich detail is the strongest evidence for the answer, \"The students gathered more than one kind of weather evidence.\"?","choices":["They measured rainfall, wind direction, temperature, and cloud cover every day.","The music teacher tuned a violin before class.","The passage says every reader already knew about weather station.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To find evidence in a text, look for specific details or examples that directly support the answer you are trying to prove.","example":"If the claim is 'The dog is messy', the evidence would be 'The dog tracked mud on the rug' rather than 'The dog is fluffy'.","strategyClue":"Look at the question to identify the specific claim being made, then scan the text for a list of items or actions that specifically address that claim.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They measured rainfall, wind direction, temperature, and cloud cover every day. This sentence lists four distinct types of data the students collected, which provides direct proof that they gathered more than one kind of weather evidence.","incorrect":["",{"choice":"The music teacher tuned a violin before class.","category":"irrelevant information","reason":"This sentence describes a music class and has nothing to do with the science students or the weather evidence mentioned in the passage."},{"choice":"The passage says every reader already knew about weather station.","category":"unsupported claim","reason":"This information is not found in the passage, and even if it were, it would not explain the types of data the students personally gathered."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"A title might introduce a topic, but it does not provide the specific details or measurements needed to prove that multiple types of evidence were collected."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":160,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0161","version":3,"contentHash":"sha256:280c02e1865904a15768a2f8876f6a5c0d715e3cff8f4778552a3b76231d86be","question":"Read the passage. Grade 5 developing passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. These details show that a recycling team used bins and reminders to reduce paper waste.\n\nWhich sentence from the passage best supports this idea: The plan changed how much paper the school used.","choices":["The nurse checked the first-aid supplies after lunch.","By winter break, the school ordered fewer boxes of printer paper.","The passage says every reader already knew about recycling team.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To support a main idea, choose a sentence that provides direct evidence, facts, or results related to that specific claim.","example":"Claim: The garden grew well. Evidence: We harvested ten pounds of tomatoes.","strategyClue":"Identify the key result mentioned in the claim (e.g., a change in quantity) and scan the text for a sentence that provides data or proof of that exact change.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: By winter break, the school ordered fewer boxes of printer paper. This sentence directly shows a measurable decrease in paper consumption, which proves that the team's plan was effective.","incorrect":[{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence mentions a nurse and first-aid, which has nothing to do with recycling or the amount of paper the school uses."},"",{"choice":"The passage says every reader already knew about recycling team.","category":"factually incorrect claim","reason":"This statement is not found in the text, and it does not provide evidence that the amount of paper used changed."},{"choice":"The title names the topic but gives no proof.","category":"incorrect analytical claim","reason":"While a title identifies a topic, this sentence does not help prove that paper usage decreased, which is the main goal of the question."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":161,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0162","version":3,"contentHash":"sha256:c3c1b3060e8d202c6f3ddc2be91982cd81cfd58a13fb7a78aa8275c835441b2a","question":"Read the passage. Grade 5 developing passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. These details show that museum workers created an exhibit that helped visitors learn local history.\n\nWhich detail is the strongest evidence for the answer, \"The exhibit included both objects and personal stories.\"?","choices":["The passage says every reader already knew about museum exhibit.","A rainstorm delayed the baseball game.","Visitors could press buttons to hear recordings of elders telling memories.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Strong evidence must directly support the claim by mentioning specific examples from the text that relate to both parts of the main idea.","example":"Claim: 'The pet store has many types of animals.' Evidence: 'Customers could see barking puppies, swimming goldfish, and sleeping hamsters.'","strategyClue":"Identify the two key parts of the claim you are proving (in this case, 'objects' and 'personal stories'). Look for the sentence that mentions items you can see and sounds you can hear.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Visitors could press buttons to hear recordings of elders telling memories. This detail provides direct evidence of personal stories, while the tools, photographs, letters, and map represent the physical objects included in the exhibit.","incorrect":[{"choice":"The passage says every reader already knew about museum exhibit.","category":"Unsupported claim","reason":"The text never makes this statement, and even if it did, it provides no information about the contents of the exhibit."},{"choice":"A rainstorm delayed the baseball game.","category":"Irrelevant information","reason":"This information is not found in the text and has no connection to the museum exhibit or its contents."},"",{"choice":"The title names the topic but gives no proof.","category":"Logical fallacy","reason":"While titles can be helpful, the question asks for evidence found within the text to support a specific claim about the exhibit's features."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":162,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0163","version":3,"contentHash":"sha256:08c03dc75d3f508b0016806e02a3f874467c1a3610f475e005d2befe694331af","question":"Read the passage. Grade 5 developing passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. These details show that club members tested a robot, changed its code, and used notes to improve it.\n\nWhich sentence from the passage best supports this idea: The club used mistakes as information.","choices":["The title names the topic but gives no proof.","The principal announced picture day over the speaker.","The passage says every reader already knew about robotics club.","Each time the robot missed a turn, members adjusted the code and tested again."],"correct":3,"studyAid":{"definition":"To find evidence that supports an idea, look for sentences that describe specific actions or examples of the idea in practice.","example":"Idea: The kitchen was messy. Evidence: Flour covered the floor and dishes were piled high in the sink.","strategyClue":"Look for the sentence that describes a specific problem or error occurring, followed immediately by an action taken to fix it. That connection between a problem and a solution is the evidence you need.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Each time the robot missed a turn, members adjusted the code and tested again. This sentence shows the club identifying a 'mistake' (the robot missing a turn) and using that event as data to 'adjust' (improve) the code.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"lacks supporting evidence","reason":"A title is just a label for the passage; it does not contain the actions or observations needed to prove that mistakes were used as information."},{"choice":"The principal announced picture day over the speaker.","category":"irrelevant information","reason":"This sentence describes an event completely unrelated to the robotics club or the process of improving a robot through trial and error."},{"choice":"The passage says every reader already knew about robotics club.","category":"incorrect inference","reason":"The passage does not state that readers were already experts, and even if it did, this would not explain how the club members learned from their specific mistakes."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":163,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0164","version":3,"contentHash":"sha256:d14b9d4d7320b6ab6555f93986a5b8b05656ec777aa381c1bdf54da1087042a3","question":"Read the passage. Grade 5 developing passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. These details show that school leaders made breakfast easier for busy students to get.\n\nWhich detail is the strongest evidence for the answer, \"The cart was designed for students with little time before class.\"?","choices":["Students who arrived close to the bell could still choose a quick meal.","The science lab received new magnifying glasses.","The passage says every reader already knew about school breakfast.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Supporting evidence is a specific fact or detail from the text that proves a statement is true.","example":"Statement: 'The park is popular.' Evidence: 'Dozens of families were sitting on blankets near the pond.'","strategyClue":"Look for keywords in the question, such as 'time' or 'little time,' and scan the passage to find a sentence that describes a situation involving those specific concepts.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Students who arrived close to the bell could still choose a quick meal. This detail directly supports the claim that the cart was designed for students with little time, as it specifically mentions the timing (close to the bell) and the speed (quick meal) of the service.","incorrect":["",{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information","reason":"This sentence mentions a science lab and tools, which has nothing to do with the breakfast cart or the time students have before class."},{"choice":"The passage says every reader already knew about school breakfast.","category":"unsupported claim","reason":"The passage does not state that readers already knew about the breakfast program. Evidence must be found directly in the text, not from assumptions about what readers know."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"A title is not a detail from the text. To find evidence, you must look for specific sentences in the body of the passage that prove your point."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":164,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0165","version":3,"contentHash":"sha256:95a7c2c88c130495cdef7346490ddd3918364d2f7f8343add5817029867cb024","question":"Read the passage. Grade 5 developing passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. These details show that park rangers marked a trail so visitors could navigate and learn.\n\nWhich sentence from the passage best supports this idea: The signs gave visitors both directions and information.","choices":["The post office closed early on Saturday.","They added arrows, distance signs, and small plaques naming common trees.","The passage says every reader already knew about nature trail.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence in a text, look for specific details that directly show or prove the main idea being discussed.","example":"Main idea: 'The park is fun.' Supporting detail: 'There is a large playground and a colorful splash pad.'","strategyClue":"Look for the specific nouns or objects mentioned in the summary sentence (directions/information) and see which option lists physical items that match those categories.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They added arrows, distance signs, and small plaques naming common trees. This sentence directly lists physical items (arrows and signs for directions, plaques for information) that provide visitors with the help described in the prompt.","incorrect":[{"choice":"The post office closed early on Saturday.","category":"irrelevant information","reason":"This sentence is not part of the passage and mentions a post office, which has nothing to do with park rangers or a nature trail."},"",{"choice":"The passage says every reader already knew about nature trail.","category":"misreading the passage","reason":"The passage never mentions the reader's prior knowledge; it describes actions the rangers took to help visitors."},{"choice":"The title names the topic but gives no proof.","category":"not a supporting sentence","reason":"While this might be a comment about how titles work, it is not a sentence from the passage that provides evidence of the rangers' actions."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":165,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0166","version":3,"contentHash":"sha256:6edef494d3295cef35101a1b6b22b6d8360f5b7b59865e0ba0698ff2d5cd47a8","question":"Read the passage. Grade 5 challenge passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. Because the passage connects actions with results, readers can see why daily care helped the school garden grow well.\n\nWhich sentence from the passage best supports this idea: The students used observations to care for the plants.","choices":["The passage says every reader already knew about school garden.","The art room displayed clay bowls near the window.","They recorded how tall the seedlings grew.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To support a claim, you must identify a specific sentence from the text that provides factual proof or a clear example of the idea.","example":"Claim: 'The dog was hungry.' Support: 'The dog stared at the bowl and whined for food.'","strategyClue":"Look for keywords in the claim, such as 'observations' or 'tracking,' and scan the text for a sentence that describes that exact action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They recorded how tall the seedlings grew. This sentence provides evidence that students observed their progress, which directly relates to using observations to track plant health and growth.","incorrect":[{"choice":"The passage says every reader already knew about school garden.","category":"not in text","reason":"This information does not appear in the text provided. When looking for evidence, you must only use facts directly stated in the passage."},{"choice":"The art room displayed clay bowls near the window.","category":"irrelevant information","reason":"While this sentence might be true in a different context, it does not mention the garden, seedlings, or observations. It is unrelated to the topic of plant care."},"",{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"This choice discusses the structure of a title rather than providing the specific evidence from the text about how students cared for the plants."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":166,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0167","version":3,"contentHash":"sha256:46ab1b671b6b5eee97a8a3d58e2a248c40d09d08eaf546378475cdb63e0d4b5d","question":"Read the passage. Grade 5 challenge passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. Because the passage connects actions with results, readers can see why student helpers organized the library so readers could find books faster.\n\nWhich detail is the strongest evidence for the answer, \"The volunteers helped readers find materials more efficiently.\"?","choices":["The title names the topic but gives no proof.","The cafeteria served tomato soup on Thursday.","The passage says every reader already knew about library helpers.","They sorted returned books by call number before placing them on shelves."],"correct":3,"studyAid":{"definition":"Evidence is a specific detail from a text that directly proves a claim or explains why a statement is true.","example":"Claim: The classroom was messy. Evidence: Papers were scattered across the floor and desks were pushed out of place.","strategyClue":"Focus on the goal of the claim—in this case, 'efficiency.' Ask yourself which action directly describes a process that saves time or makes finding items easier.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This detail directly explains the system used to organize books, which allows readers to locate specific materials quickly, thus supporting the idea of increased efficiency.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"Titles describe what a text is about, but they do not provide specific actions or evidence that demonstrate how a task was made more efficient."},{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This statement is about food services and has no connection to library organization or how readers find books in the library."},{"choice":"The passage says every reader already knew about library helpers.","category":"unsupported claim","reason":"The passage never mentions the readers' prior knowledge of the helpers; furthermore, knowing about helpers does not prove that books were found more efficiently."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":167,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0168","version":3,"contentHash":"sha256:96e27249aaf57b59e980eb1cddca6fa3c695acc195f2f375c34332d2505733ea","question":"Read the passage. Grade 5 challenge passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. Because the passage connects actions with results, readers can see why a rain barrel helped the club save water for plants.\n\nWhich sentence from the passage best supports this idea: The rain barrel reduced the need for hose water.","choices":["Members used the stored water on dry afternoons instead of turning on the hose.","A soccer team practiced corner kicks after school.","The passage says every reader already knew about rain barrel.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To support a claim, choose evidence that directly links the cause (the rain barrel) to the result (not using the hose).","example":"Claim: The library is quiet. Evidence: Students whispered while they studied at their desks.","strategyClue":"Look for the sentence that describes the action of switching from the 'old' way of doing things (using the hose) to the 'new' way (using the stored water).","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Members used the stored water on dry afternoons instead of turning on the hose. This sentence shows the direct replacement of hose water with collected rainwater, which explains how the club saved water.","incorrect":["",{"choice":"A soccer team practiced corner kicks after school.","category":"irrelevant information","reason":"This sentence is about soccer, not science or rainwater. It does not provide any evidence for how the rain barrel helped save water."},{"choice":"The passage says every reader already knew about rain barrel.","category":"unsupported claim","reason":"The passage does not state that readers already knew about rain barrels. Even if it did, this would not explain how the barrel helps reduce hose usage."},{"choice":"The title names the topic but gives no proof.","category":"unsupported claim","reason":"This sentence describes the title, not the actual usage of the barrel. It doesn't prove that using the barrel reduces the need for the hose."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":168,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0169","version":3,"contentHash":"sha256:d06563757a6092ad0b466909cee45bd08899b7ecdc3753137e44a4cfc60649da","question":"Read the passage. Grade 5 challenge passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. Because the passage connects actions with results, readers can see why the class newspaper gave students a careful way to share school news.\n\nWhich detail is the strongest evidence for the answer, \"The reporters tried to make the newspaper accurate.\"?","choices":["The playground slide was painted blue over spring break.","They interviewed teachers, wrote short articles, and checked facts before printing.","The passage says every reader already knew about class newspaper.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence for a claim, look for text that directly explains the 'how' or 'why' behind an action described in the statement.","example":"Claim: The chef was careful. Evidence: He measured every ingredient three times before mixing.","strategyClue":"Look for verbs in the text that show intentional actions related to quality control, such as checking, verifying, or refining, to find support for claims about accuracy.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They interviewed teachers, wrote short articles, and checked facts before printing. This sentence lists the specific steps taken to verify and prepare the information, which directly supports the claim that the reporters were focused on accuracy.","incorrect":[{"choice":"The playground slide was painted blue over spring break.","category":"irrelevant information","reason":"This detail describes school property, not the process of creating or verifying the newspaper, so it provides no evidence for the reporters' goal of accuracy."},"",{"choice":"The passage says every reader already knew about class newspaper.","category":"unsupported claim","reason":"This statement is not found in the text and does not address the reporters' efforts to be accurate in their reporting."},{"choice":"The title names the topic but gives no proof.","category":"missing textual support","reason":"A title cannot provide evidence for the quality of the work inside the paper, and this choice does not point to any specific actions taken by the students."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":169,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0170","version":3,"contentHash":"sha256:1f81b9fb363577dd1f5b143d2e3317262e1e7a4648c25d2a756cbb5b313ef7b2","question":"Read the passage. Grade 5 challenge passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. Because the passage connects actions with results, readers can see why the cleanup protected the beach by removing harmful litter.\n\nWhich sentence from the passage best supports this idea: The cleanup made the beach safer for wildlife.","choices":["The passage says every reader already knew about beach cleanup.","The town band played a concert in the park.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting evidence consists of specific details, facts, or examples from the text that prove an idea or claim is true.","example":"Claim: The garden is healthy. Evidence: The roses are blooming and the soil is damp.","strategyClue":"Identify the claim (the 'what' or 'why'), then look for the sentence that lists concrete objects or actions that act as proof for that claim.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides evidence that the beach is now safer because it lists the specific, dangerous objects (like fishing line and plastic) that were removed from the environment.","incorrect":[{"choice":"The passage says every reader already knew about beach cleanup.","category":"not in text","reason":"The passage does not state that readers already knew this, and this statement does not describe any cleanup action that would protect wildlife."},{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This information is not found in the passage and has no connection to beach cleanup or protecting wildlife."},"",{"choice":"The title names the topic but gives no proof.","category":"missing textual evidence","reason":"While a title might name a topic, it does not provide the supporting evidence needed to show how the action of cleaning resulted in a safer environment for wildlife."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":170,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0171","version":3,"contentHash":"sha256:13c2a222378341743764c7fe8728c5d364ec0de9aaf184d7d30910d4bd0cbb34","question":"Read the passage. Grade 5 challenge passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. Because the passage connects actions with results, readers can see why bike riders can prevent injuries by following safety rules.\n\nWhich detail is the strongest evidence for the answer, \"A helmet must fit correctly to protect a rider.\"?","choices":["The title names the topic but gives no proof.","The school choir rehearsed a song about the moon.","The passage says every reader already knew about bike safety.","She showed how helmets should sit flat and snug on a rider's head."],"correct":3,"studyAid":{"definition":"Strong evidence is a specific detail from the text that directly explains, proves, or supports the main idea of your answer.","example":"Claim: The classroom was messy. Evidence: Papers were scattered across the floor and books were piled on the chairs.","strategyClue":"Highlight the key words in the question, such as 'helmet' and 'fit'. Scan the text for sentences that describe these specific concepts to see which one provides the most concrete detail.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She showed how helmets should sit flat and snug on a rider's head. This sentence provides specific instructions on the physical fit of a helmet, which directly supports the claim that a helmet must fit correctly to provide protection.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"This is a general statement about titles, but the passage does not provide a title. Look for a sentence within the text that describes the physical requirement of the helmet."},{"choice":"The school choir rehearsed a song about the moon.","category":"off-topic choice","reason":"This detail is completely unrelated to bike safety or how a helmet should be worn. Always check if the evidence matches the specific topic of the question."},{"choice":"The passage says every reader already knew about bike safety.","category":"unsupported claim","reason":"The passage never states that riders already knew these rules; in fact, the safety officer is teaching them. Evidence must be found directly in the text provided."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":171,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0172","version":3,"contentHash":"sha256:15be02b7edd23a29f13e919b6ca01b1884d52c0f900f150434f6381485725705","question":"Read the passage. Grade 5 challenge passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. Because the passage connects actions with results, readers can see why new bus routes made important places easier to reach.\n\nWhich sentence from the passage best supports this idea: The new bus route served community needs.","choices":["The new route stopped near the clinic, grocery store, and community center.","A bakery sold cinnamon rolls before sunrise.","The passage says every reader already knew about city buses.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Supporting evidence consists of specific details or facts from the text that prove a claim or main idea is true.","example":"Claim: The park is a popular spot. Supporting evidence: The park benches were full and children were playing on all the swings.","strategyClue":"Identify the key terms in the claim (like 'community needs'), then look for the sentence in the text that lists places where people go to meet those specific needs.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The new route stopped near the clinic, grocery store, and community center. This sentence provides direct evidence of the bus route connecting to essential neighborhood locations, which supports the claim that it serves community needs.","incorrect":["",{"choice":"A bakery sold cinnamon rolls before sunrise.","category":"irrelevant information","reason":"This sentence describes a bakery, which has nothing to do with transportation planning or the bus routes mentioned in the passage."},{"choice":"The passage says every reader already knew about city buses.","category":"factually incorrect claim","reason":"The passage never makes this claim. Even if it did, knowing about buses does not prove that a specific route serves community needs."},{"choice":"The title names the topic but gives no proof.","category":"unsupported analytical claim","reason":"This choice discusses the structure of a title rather than providing evidence from the text to support the idea that the bus route helps the community."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":172,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0173","version":3,"contentHash":"sha256:ae8a3d9029e4428524a00e73c6003912b81574f27b4d35777c8bd7237d666433","question":"Read the passage. Grade 5 challenge passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. Because the passage connects actions with results, readers can see why many students worked together to prepare the school play.\n\nWhich detail is the strongest evidence for the answer, \"The production required more than acting.\"?","choices":["A math poster showed different kinds of triangles.","Actors practiced lines while stage crew members painted scenery and tested lights.","The passage says every reader already knew about school play.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence, look for specific details or actions in the text that directly support the point being made.","example":"Claim: 'The cat was hungry.' Evidence: 'The cat meowed loudly and stared at its empty food bowl.'","strategyClue":"Look for a sentence that lists different roles or jobs being performed. Compare those roles against the definition of 'acting' to see which sentence proves other tasks were involved.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence provides evidence that people other than actors, such as stage crew members, were necessary for the play to function.","incorrect":[{"choice":"A math poster showed different kinds of triangles.","category":"irrelevant information","reason":"This information is not mentioned in the passage and does not relate to the teamwork required for a theater production."},"",{"choice":"The passage says every reader already knew about school play.","category":"unsupported claim","reason":"The text does not claim that every reader knows about the play; it describes the specific actions students took to prepare it."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"While titles identify a topic, the question asks for a specific detail from the text that proves multiple roles were needed beyond acting."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":173,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0174","version":3,"contentHash":"sha256:8f3cfdfbeab5c2712e057bbe2261a9bb8cd11762691d7669ac059c41dd3c0e4b","question":"Read the passage. Grade 5 challenge passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. Because the passage connects actions with results, readers can see why composting changed cafeteria scraps into useful soil material.\n\nWhich sentence from the passage best supports this idea: Food scraps can become useful instead of being thrown away.","choices":["The passage says every reader already knew about compost bin.","A new scoreboard was installed in the gym.","After several weeks, the dark compost was mixed into flower beds.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting details are the sentences or facts in a passage that provide proof for a main idea or argument.","example":"Main idea: Dogs are helpful. Evidence: My dog helped me find my lost keys.","strategyClue":"Identify the main idea you are trying to prove, then scan each option to see which one provides a direct example of that specific action or result occurring.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After several weeks, the dark compost was mixed into flower beds. This sentence provides direct evidence of the transformation process, showing that the scraps (compost) were used for a productive purpose in the garden rather than being discarded.","incorrect":[{"choice":"The passage says every reader already knew about compost bin.","category":"unsupported information","reason":"The passage never states that readers already knew about the bin. Furthermore, this sentence does not provide evidence of how the scraps were used."},{"choice":"A new scoreboard was installed in the gym.","category":"irrelevant information","reason":"This detail is completely unrelated to food scraps or composting. It does not support the idea that waste can be turned into useful soil."},"",{"choice":"The title names the topic but gives no proof.","category":"incorrect text analysis","reason":"This statement acts as a commentary on the passage structure rather than finding evidence within the story about the process of composting."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":174,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0175","version":3,"contentHash":"sha256:e0d4b06f51d29d0d6698b967881be52ff311c42d3f9589ba0beb231a281b28ec","question":"Read the passage. Grade 5 challenge passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. Because the passage connects actions with results, readers can see why students collected weather data to notice local patterns.\n\nWhich detail is the strongest evidence for the answer, \"The students gathered more than one kind of weather evidence.\"?","choices":["The title names the topic but gives no proof.","The music teacher tuned a violin before class.","The passage says every reader already knew about weather station.","They measured rainfall, wind direction, temperature, and cloud cover every day."],"correct":3,"studyAid":{"definition":"To find evidence, look for specific details or lists in the text that directly support or prove the claim being made.","example":"Claim: 'The basket had many fruits.' Evidence: 'The basket was filled with apples, oranges, and bananas.'","strategyClue":"Scan the text for sentences that list specific actions or items. If a claim mentions 'more than one' of something, look for a part of the text that names several different items in a series.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They measured rainfall, wind direction, temperature, and cloud cover every day. This sentence lists four distinct types of data gathered, which directly proves the students collected more than one kind of evidence.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"Titles often introduce a topic, but they do not provide specific data or evidence to support a claim about the students' actual actions."},{"choice":"The music teacher tuned a violin before class.","category":"unrelated topic","reason":"This sentence describes a music class and has no connection to weather, science, or the activities performed by the students."},{"choice":"The passage says every reader already knew about weather station.","category":"unsupported claim","reason":"The passage does not state that readers already knew about weather stations, and even if it did, that information would not prove that the students gathered multiple types of data."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":175,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0176","version":3,"contentHash":"sha256:c4b82d3b877000244656075af5db0d508c3a26f736327b8b16098d24d1fd115d","question":"Read the passage. Grade 5 challenge passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. Because the passage connects actions with results, readers can see why the recycling team helped the school waste less paper.\n\nWhich sentence from the passage best supports this idea: The plan changed how much paper the school used.","choices":["By winter break, the school ordered fewer boxes of printer paper.","The nurse checked the first-aid supplies after lunch.","The passage says every reader already knew about recycling team.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To support a claim, you must identify a specific sentence that provides evidence or a result linked to the main idea.","example":"Claim: The plant grew fast. Evidence: The plant grew three inches in just one week.","strategyClue":"Look for the sentence that shows a measurable change, such as a drop or increase in numbers, to confirm the outcome of the plan described.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: By winter break, the school ordered fewer boxes of printer paper. This sentence directly provides evidence of a result—ordering fewer boxes—caused by the previous action of using both sides of paper.","incorrect":["",{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence is not about recycling or paper usage, so it cannot support the claim that the school's paper use changed."},{"choice":"The passage says every reader already knew about recycling team.","category":"unsupported claim","reason":"The passage never mentions what readers knew; it describes the actions taken by the recycling team."},{"choice":"The title names the topic but gives no proof.","category":"irrelevant structural comment","reason":"Whether the title gives proof or not does not show how the school's paper usage changed."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":176,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0177","version":3,"contentHash":"sha256:ff3ff6554812ff51b34d9aaba918a02c84af336136303b2be5179fad1da0da2d","question":"Read the passage. Grade 5 challenge passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. Because the passage connects actions with results, readers can see why the exhibit used artifacts and voices to teach local history.\n\nWhich detail is the strongest evidence for the answer, \"The exhibit included both objects and personal stories.\"?","choices":["A rainstorm delayed the baseball game.","Visitors could press buttons to hear recordings of elders telling memories.","The passage says every reader already knew about museum exhibit.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Strong evidence must directly support the claim being made by mentioning specific details from the text that match the key parts of the claim.","example":"Claim: The park has flowers. Evidence: 'Tulips and roses lined the walkway.' (Matches the claim). Evidence: 'The slide is made of plastic.' (Does not match the claim).","strategyClue":"Break your target claim into two parts (e.g., 'objects' and 'personal stories'). Look for the sentence in the text that mentions both of those components specifically.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Visitors could press buttons to hear recordings of elders telling memories. This sentence provides direct evidence for the presence of 'personal stories' through the recordings of elders, while the mention of 'old tools, photographs, letters, and a map' accounts for the 'objects'.","incorrect":[{"choice":"A rainstorm delayed the baseball game.","category":"irrelevant information","reason":"This information is not mentioned in the passage and has nothing to do with the exhibit or the artifacts on display."},"",{"choice":"The passage says every reader already knew about museum exhibit.","category":"unsupported claim","reason":"The passage never states that readers already knew about the exhibit; this choice does not provide evidence for the types of materials used."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"A title might introduce a subject, but it cannot act as evidence to prove what was included inside the exhibit itself."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":177,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0178","version":3,"contentHash":"sha256:632e226b1bcd648d24c8ef44f09b7a3e1e3dfdf6793a339e321f4303240614e5","question":"Read the passage. Grade 5 challenge passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. Because the passage connects actions with results, readers can see why testing and revising helped the robotics club improve its robot.\n\nWhich sentence from the passage best supports this idea: The club used mistakes as information.","choices":["The passage says every reader already knew about robotics club.","The principal announced picture day over the speaker.","Each time the robot missed a turn, members adjusted the code and tested again.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting evidence is a specific detail from a text that proves or explains a main idea or claim.","example":"Claim: Dogs are helpful. Supporting evidence: Some dogs are trained to guide people who cannot see.","strategyClue":"First, identify the specific point the claim is making. Then, scan the text for a sentence that describes a 'cause and effect' relationship related to that point.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Each time the robot missed a turn, members adjusted the code and tested again. This sentence shows the club learning from a 'mistake' (missing a turn) by adjusting their approach, which directly supports the idea that they used mistakes as information.","incorrect":[{"choice":"The passage says every reader already knew about robotics club.","category":"not in text","reason":"This statement is not found in the passage provided. Even if it were, it does not explain how the club uses mistakes to improve."},{"choice":"The principal announced picture day over the speaker.","category":"irrelevant information","reason":"This information is not part of the passage and is completely unrelated to the robotics club or the process of fixing a robot."},"",{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title might introduce a topic, but it does not provide the specific actions or 'proof' needed to show how the club used their errors to get better."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":178,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0179","version":3,"contentHash":"sha256:7319c32a112111cbf1c5e748bd4214ffe5c22c886d24aa30ec523772c358e996","question":"Read the passage. Grade 5 challenge passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. Because the passage connects actions with results, readers can see why the breakfast cart helped more students start the day with food.\n\nWhich detail is the strongest evidence for the answer, \"The cart was designed for students with little time before class.\"?","choices":["The title names the topic but gives no proof.","The science lab received new magnifying glasses.","The passage says every reader already knew about school breakfast.","Students who arrived close to the bell could still choose a quick meal."],"correct":3,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly proves or supports a claim or idea.","example":"Claim: 'The pet was scared.' Evidence: 'The dog hid under the bed and trembled when the thunder started.'","strategyClue":"Highlight the keywords in the claim (like 'little time' and 'designed for'). Then, scan the text for sentences that mention time constraints and how the cart solved that problem.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Students who arrived close to the bell could still choose a quick meal. This sentence specifically describes students who are in a rush ('arrived close to the bell') and their ability to successfully get food ('could still choose a quick meal'), which directly supports the idea that the cart was designed for those with little time.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant reasoning","reason":"This is a general statement about titles, but it does not provide any specific facts from the text that explain why the cart was helpful for busy students."},{"choice":"The science lab received new magnifying glasses.","category":"off-topic information","reason":"This detail is completely unrelated to the breakfast cart or student schedules. Always look for evidence that directly addresses the specific claim being made."},{"choice":"The passage says every reader already knew about school breakfast.","category":"unsupported claim","reason":"The passage does not state that readers already knew this, and even if it did, it would not explain the cart's design for students with limited time."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":179,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0180","version":3,"contentHash":"sha256:78ac568adc4a0727f90c10636aaf27f8385bcbc68cc3fa6acb5b364662980da6","question":"Read the passage. Grade 5 challenge passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. Because the passage connects actions with results, readers can see why trail signs helped visitors move safely and learn about nature.\n\nWhich sentence from the passage best supports this idea: The signs gave visitors both directions and information.","choices":["They added arrows, distance signs, and small plaques naming common trees.","The post office closed early on Saturday.","The passage says every reader already knew about nature trail.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To support an idea, choose evidence that specifically connects to the claim being made rather than just talking about the topic generally.","example":"Claim: 'The pet store was busy.' Evidence: 'Three customers were waiting in line, and the phones were ringing constantly.'","strategyClue":"Look for keywords in the claim, such as 'directions' and 'information', and scan the choices for specific words or actions that match those categories.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They added arrows, distance signs, and small plaques naming common trees. This sentence provides direct evidence because it lists 'arrows' (directions) and 'plaques naming common trees' (information).","incorrect":["",{"choice":"The post office closed early on Saturday.","category":"irrelevant information","reason":"This sentence is not part of the passage and does not mention park trails, signs, or visitor information."},{"choice":"The passage says every reader already knew about nature trail.","category":"not in text","reason":"The text does not state that readers already knew about the trail; this information is not found in the passage."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"This does not provide an example of signs or information from the passage, which is what the prompt requires to support the idea."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":180,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0181","version":3,"contentHash":"sha256:8af315f8c5eb839e92b602acbb9c427d30c404491f254365794ec792a46e3579","question":"Read the statement. Mary wrote, “Everyone should drink milk instead of coffee. My grandfather drank milk at every meal. He lived to be 89. People could live longer by drinking milk.” What is faulty with Mary’s reasoning?","choices":["Not enough evidence to decide what is good for everyone","Other factors may have been a reason for his long life","Both A and B","There is nothing wrong with Mary’s reasoning."],"correct":2,"explanation":{"correct":"Answer: Both A and B. Mary uses a single example of one person to make a broad claim about everyone, which is not enough evidence. Additionally, she fails to consider other factors like exercise or genetics that could have contributed to his long life.","incorrect":[{"choice":"Not enough evidence to decide what is good for everyone","category":"insufficient evidence fallacy","reason":"While this is true, it is only part of why her reasoning is faulty. By ignoring other potential causes for health, this choice misses half of the problem."},{"choice":"Other factors may have been a reason for his long life","category":"overlooking hidden variables","reason":"This is a correct observation, but it is not the only problem. Mary also lacks enough evidence to turn one person's experience into a rule for the whole population."},"",{"choice":"There is nothing wrong with Mary’s reasoning.","category":"logical reasoning error","reason":"Mary is making a 'hasty generalization' by assuming that because one person lived a long time while drinking milk, milk must be the sole reason for his long life."}]},"studyAid":{"definition":"Faulty reasoning happens when someone makes a claim without enough evidence or ignores other possible explanations for an event.","example":"Faulty: My dog wears a red collar and is fast, so all red collars make dogs fast. Better: My dog runs three miles a day, which might help him stay fast.","strategyClue":"Ask yourself: Does this evidence definitely prove the claim, or could something else be happening? Look for logical gaps where a conclusion jumps too far from the provided facts.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets - Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["reading comprehension","reading","evidence","grade 3"],"feedbackFocus":"use the passage or word clue and compare each answer choice to the evidence","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-1_Foundational skills and vocabulary.pdf","sourceQuestionNumber":3,"sourceCategory":"foundational-skills-vocabulary","sourceGrade":3,"sequence":181,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0182","version":3,"contentHash":"sha256:7175d3f71960f26d10740accb8a646b0bf8f593fffce532a1396c157fee6282f","question":"Study the NFL football standings. How many losses have the New York Jets had so far this season?","choices":["5","3","4","0"],"correct":0,"explanation":{"correct":"Answer: 5. Based on current NFL official standings for the 2024 season, the New York Jets have recorded 5 losses.","incorrect":["",{"choice":"3","category":"factual inaccuracy","reason":"This number is lower than the actual total of losses recorded by the team this season."},{"choice":"4","category":"factual inaccuracy","reason":"Although this is close, it does not match the specific data provided in the current official NFL standings."},{"choice":"0","category":"factual inaccuracy","reason":"The team has experienced multiple losses this season, so zero is an incorrect count."}]},"studyAid":{"definition":"Reading comprehension requires locating specific facts within a provided text or reliable data source.","example":"Question: 'How many apples did Sam buy?' Text: 'Sam bought 5 apples.' Answer: 5.","strategyClue":"Scan the provided data source specifically for the team name mentioned in the prompt, then identify the column labeled 'Losses' or 'L' to find the corresponding number.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-1_Informational Text.pdf","sourceQuestionNumber":10,"sourceCategory":"informational-text","sourceGrade":3,"sequence":182,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0183","version":3,"contentHash":"sha256:2f9364391fc415466d36e41c517f5afce5f786f4d46c34b5346cb3ad179da289","question":"Read the passage. What can be concluded about the Bed and Breakfast?","choices":["Itwould be a good place to stay.","There are norooms left torent.","The owner likes to play the piano.","The owner is a gardener."],"correct":0,"explanation":{"correct":"Answer: It would be a good place to stay. This conclusion is supported by descriptive details in the text, such as positive adjectives or comfortable amenities mentioned by the author.","incorrect":["",{"choice":"There are norooms left torent.","reason":"\"There are norooms left torent.\" does not give the clearest proof for the idea the question asks about."},{"choice":"The owner likes to play the piano.","category":"Irrelevant detail","reason":"Even if the owner plays the piano, the passage does not provide evidence for this hobby. Avoid choosing details that aren't mentioned in the text."},{"choice":"The owner is a gardener.","category":"Unsupported inference","reason":"While the passage might mention flowers or a lawn, that does not necessarily mean the owner is a professional gardener. Only draw conclusions that are clearly backed by the passage."}]},"studyAid":{"definition":"A conclusion is a decision or opinion formed by combining what you already know with the clues given in the text.","example":"Text: 'The sky was dark and gray, and thunder rumbled.' Conclusion: It is going to rain.","strategyClue":"Look for specific sentences in the text that act as evidence. If you cannot point to a word or phrase that proves your answer, it is likely not a supported conclusion.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-2_Informational Text.pdf","sourceQuestionNumber":1,"sourceCategory":"informational-text","sourceGrade":3,"sequence":183,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0184","version":3,"contentHash":"sha256:c24b1306269569b2f9461c746e80747852a32984cc66b0875135642828afc767","question":"Read the following logical argument. Some people are creative, some people are ambitious, and all people are curious. If these statements are facts, which one of the following sentences is definitely true?","choices":["all people are ambitious","some curious people are creative","curious people are never ambitious","ambitious people are always creative"],"correct":1,"explanation":{"correct":"Answer: some curious people are creative. Since all people are curious, the set of 'all people' is contained within the set of 'curious people'. Because some of those people are creative, those specific individuals must also be part of the 'curious' group.","incorrect":[{"choice":"all people are ambitious","category":"overgeneralization error","reason":"The prompt only states that 'some' people are ambitious, not all. We cannot assume that everyone shares this trait based on the provided facts."},"",{"choice":"curious people are never ambitious","reason":"\"curious people are never ambitious\" does not give the clearest proof for the idea the question asks about."},{"choice":"ambitious people are always creative","category":"logical leap error","reason":"The prompt describes creative people and ambitious people as separate groups that may overlap, but it does not say that one trait always leads to the other."}]},"studyAid":{"definition":"A logical conclusion must be true based ONLY on the facts provided; if a statement adds information that wasn't given, it cannot be definitely true.","example":"Fact: All dogs are mammals. Conclusion: Some mammals are dogs (True). Fact: All dogs are mammals. Conclusion: All mammals are dogs (False).","strategyClue":"Draw small circles to represent the groups mentioned. See if the circles MUST touch or overlap based strictly on the rules provided in the prompt.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-2_Informational Text.pdf","sourceQuestionNumber":2,"sourceCategory":"informational-text","sourceGrade":3,"sequence":184,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0185","version":3,"contentHash":"sha256:b124aa0e2c99bb49d47aaa6440d2880f3e105cbf3fc6b2b3edc28535f9891bf5","question":"Read the passage and answer the question. The sun was shining in the bright, blue sky. It was beautiful weather for this time of year. Beads of sweat formed on Robert’s face as he pedaled up the street. “I can’t wait to swim when we get there!” he called to Sara, who was riding ahead of him. “Yes, it will feel wonderful!” What are Robert and Sara going to do?","choices":["go shopping","go to school","go swimming","ride the bus"],"correct":2,"explanation":{"correct":"Answer: go swimming. In the passage, Robert says, 'I can’t wait to swim when we get there!', which directly indicates their intended activity.","incorrect":[{"choice":"go shopping","category":"misreading the text","reason":"There is no mention of shopping in the passage. The dialogue focuses specifically on the excitement of getting to a destination to swim."},{"choice":"go to school","category":"incorrect inference","reason":"Robert and Sara are riding bikes in the sun, which doesn't match the context of going to school. Look for the specific action mentioned in the characters' dialogue."},"",{"choice":"ride the bus","category":"contradicts passage details","reason":"The passage states that the characters are pedaling bikes, not riding a bus. Always check the text to see how the characters are traveling."}]},"studyAid":{"definition":"To find the answer to a reading comprehension question, look for specific words or actions mentioned in the text that support your choice.","example":"Text: 'She picked up her racket.' Question: 'What will she do?' Answer: Play tennis.","strategyClue":"Scan the characters' dialogue for action verbs. Identify the specific activity they are looking forward to and match it to one of the choices.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-2_Informational Text.pdf","sourceQuestionNumber":5,"sourceCategory":"informational-text","sourceGrade":3,"sequence":185,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0186","version":3,"contentHash":"sha256:536747fc5ce456fe71b22aa7159f26700cd47d408939db134a9d99a32ce443e9","question":"Read the definition. What is the second definition of fledgling?","choices":["a young bird just able to fly","ready to fly","not able to fly","a young, inexperienced person"],"correct":3,"explanation":{"correct":"Answer: a young, inexperienced person. While a fledgling is literally a young bird, the term is frequently used metaphorically to describe someone who is new to a job or activity and lacks experience.","incorrect":[{"choice":"a young bird just able to fly","category":"primary literal meaning","reason":"This is the primary, literal definition of the word. The question specifically asks for the secondary definition, which refers to people rather than animals."},{"choice":"ready to fly","category":"adjective confusion","reason":"This phrase describes the physical state of a bird, but 'fledgling' is a noun used to name the bird or person itself, not an adjective describing readiness."},{"choice":"not able to fly","category":"incorrect logic","reason":"This definition contradicts the meaning of the word. A fledgling is specifically characterized by being at the stage where it is developing or has just gained the ability to fly."},""]},"studyAid":{"definition":"A fledgling is literally a bird just learning to fly, but the word is also used to describe a person who is new to a skill or role.","example":"Literal: The fledgling fell from the nest. Metaphorical: The fledgling lawyer made a small mistake in the courtroom.","strategyClue":"Look at the options and separate those describing a bird from those describing a person. Since the question asks for a specific definition type, identify which option describes a human trait.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-2_Informational Text.pdf","sourceQuestionNumber":7,"sourceCategory":"informational-text","sourceGrade":3,"sequence":186,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0187","version":3,"contentHash":"sha256:4a6a34395e3607c9ce04cd820d5959df249f46dc895847f98c0ce80e63512ddd","question":"Read the announcement. Which of the following times canyou attend the fair?","choices":["Friday at 2:00 p.m.","Saturday at 12:00 p.m.","Saturday at 8:00 a.m.","Friday at 6:00 p.m."],"correct":1,"explanation":{"correct":"Answer: Saturday at 12:00 p.m. This is the only option listed that matches the times provided in the announcement for the fair.","incorrect":[{"choice":"Friday at 2:00 p.m.","category":"Incorrect schedule time","reason":"The announcement does not list this time for the fair. Check the text again to see if this day or time is mentioned."},"",{"choice":"Saturday at 8:00 a.m.","category":"Typographical or timing error","reason":"This choice contains a spelling error and lists a time that does not appear in the official fair announcement."},{"choice":"Friday at 6:00 p.m.","category":"Incorrect schedule time","reason":"The fair is not scheduled for this time. Always double-check your answer against the specific facts written in the text provided."}]},"studyAid":{"definition":"Reading comprehension requires finding specific facts, like times or dates, within a text to answer questions correctly.","example":"Text: 'Game at 4:00.' Choice: 'Game at 5:00' (incorrect); 'Game at 4:00' (correct).","strategyClue":"Scan the text for each specific time or day mentioned and underline them. Compare your list to the choices provided to identify the exact match.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-2_Informational Text.pdf","sourceQuestionNumber":9,"sourceCategory":"informational-text","sourceGrade":3,"sequence":187,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0188","version":3,"contentHash":"sha256:25e08e86970add593e49dc2e27ef0470d507cc4d075257bb9daf535bbe1cf243","question":"Read the sentences. 1. Peter was 13 when he sailed to America. 2. Peter lived in New York City. 3. Peter probably liked school. 4. Peter became a carpenter. What statement is not conclusive?","choices":["4","2","3","1"],"correct":2,"explanation":{"correct":"Answer: 3. The word 'probably' indicates a guess or an opinion rather than a proven fact. Because it is an assumption about Peter's feelings, it is not a conclusive statement.","incorrect":[{"choice":"4","category":"factual biographical event","reason":"This is a statement of what Peter became, which is presented as a completed historical fact in the text."},{"choice":"2","category":"factual biographical event","reason":"This describes a location where Peter lived, which is presented as a concrete, verifiable detail."},"",{"choice":"1","category":"factual biographical event","reason":"This provides a specific age and event, which functions as a direct, factual report of Peter's history."}]},"studyAid":{"definition":"A conclusive statement is a fact that can be proven true, whereas an inconclusive statement relies on guessing, opinions, or words like 'probably' or 'maybe'.","example":"Fact: He is ten years old. Inconclusive: He might be ten years old.","strategyClue":"Look for words in the sentences that suggest uncertainty, guessing, or a lack of definite proof to distinguish opinions from facts.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-3_Informational Text.pdf","sourceQuestionNumber":2,"sourceCategory":"informational-text","sourceGrade":3,"sequence":188,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0189","version":3,"contentHash":"sha256:507fbf65d3678904d870bb684799738f470c25ac8cbe32b04329230d131526b8","question":"Which of the following details indicatesthat the girl was angry?","choices":["Te ars began toroll down her face.","She stared at the rest of the class.","She slammed the door in frustration.","She didn’t utter a word."],"correct":2,"explanation":{"correct":"Answer: She slammed the door in frustration. Slamming a door is a forceful physical action that typically displays anger, and the word 'frustration' explicitly labels the emotion.","incorrect":[{"choice":"Te ars began toroll down her face.","category":"interpretation of sadness","reason":"Tears rolling down someone's face usually suggest the person is feeling sad or upset, not necessarily angry."},{"choice":"She stared at the rest of the class.","category":"neutral facial expression","reason":"Staring can happen for many reasons, such as curiosity or confusion, so it does not clearly show that the girl was feeling angry."},"",{"choice":"She didn’t utter a word.","category":"lack of evidence","reason":"Staying silent could mean the girl is shy, quiet, or just thinking; it does not provide enough information to conclude she is angry."}]},"studyAid":{"definition":"To identify an emotion in a story, look for 'clue words' that describe physical actions or internal feelings associated with that specific emotion.","example":"Angry: stomped, shouted, frowned. Happy: smiled, laughed, skipped. Sad: cried, slumped, sighed.","strategyClue":"Focus on the verbs and nouns that describe physical movement or character reactions, then ask yourself which emotion that specific action most commonly reveals.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-4_Informational Text.pdf","sourceQuestionNumber":2,"sourceCategory":"informational-text","sourceGrade":3,"sequence":189,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0190","version":3,"contentHash":"sha256:f5370090a469e3399a2c33e3cedf4d9f8aee1250594a02a8b20e9cb5eb69612a","question":"Read the letters.","choices":["I support a leash law at the community walking path. Eventhe gentlest dogs can become aggressive if they’re threatened. Keepour citizens safe – use a leash! Dr. Maury Atchley Veterinarian","A leash law is ridiculous. My dog is well trained and stays righto n my heel as I jog. I vote no! Benjamin Goe Chairman, Running Club","My classmates and I enjoy playing with the dogs down by the walking path. We have never met a meandog. Don’t deny us our rights! Sally Traynor 6th Grader","I support the leash law. I hate those dang dogs always running through my rose gardens. Keep them leashed! Harriet Mulner President, Rose Society Which writer seems most qualified to judge whether or not the town should implement a “leash law”? A. D r. Maury Atchley B. Benjamin Goe C. Sally Traynor D. Harriet Mulner"],"correct":0,"explanation":{"correct":"Answer: A. Dr. Maury Atchley is the most qualified because, as a veterinarian, he has professional expertise in animal behavior and safety, making his opinion on leashes based on scientific knowledge rather than personal preference.","incorrect":["",{"choice":"A leash law is ridiculous. My dog is well trained and stays righto n my heel as I jog. I vote no! Benjamin Goe Chairman, Running Club","category":"personal opinion bias","reason":"This writer bases his argument entirely on his own dog's behavior. While he represents a club, he lacks specific professional expertise regarding dog behavior patterns."},{"choice":"My classmates and I enjoy playing with the dogs down by the walking path. We have never met a meandog. Don’t deny us our rights! Sally Traynor 6th Grader","category":"limited perspective","reason":"While this writer is a regular path user, her opinion is based on limited personal experience rather than a broad understanding of animal safety or public policy."},{"choice":"I support the leash law. I hate those dang dogs always running through my rose gardens. Keep them leashed! Harriet Mulner President, Rose Society Which writer seems most qualified to judge whether or not the town should implement a “leash law”? A. D r. Maury Atchley B. Benjamin Goe C. Sally Traynor D. Harriet Mulner","reason":"I hate those dang dogs always running through my rose gardens. Keep them leashed! Harriet Mulner President, Rose Society Which writer seems most qualified to judge whether or not the town should implement a “leash law”? A. D r. Maury Atchley B. Benjamin Goe C. Sally Traynor D. Harriet Mulner. \"I support the leash law. I hate those dang dogs always running through my rose gardens. Keep them leashed! Harriet Mulner President, Rose Society Which writer seems most qualified to judge whether or not the town should implement a “leash law”? A. D r. Maury Atchley B. Benjamin Goe C. Sally Traynor D. Harriet Mulner\" does not give the clearest proof for the idea the question asks about."}]},"studyAid":{"definition":"A credible or qualified source is someone whose background, training, or professional experience gives them special knowledge about a specific topic.","example":"Consulting a doctor about medical health, asking a mechanic about engine trouble, or talking to a chef about cooking techniques.","strategyClue":"Look at the titles and roles provided in the text. Ask yourself: 'Which person has actually studied or worked in a field that deals directly with the subject matter?'","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-4_Informational Text.pdf","sourceQuestionNumber":3,"sourceCategory":"informational-text","sourceGrade":3,"sequence":190,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0191","version":3,"contentHash":"sha256:13d9df26bacb3daaebc714e33cbd62a55e3b916842ed609e2d05af4d793d38a0","question":"Read the catalog entry. From what material is the shirt made?","choices":["50 % cotton, 50% polyester","100% cotton","100% polyester","100% silk"],"correct":1,"explanation":{"correct":"Answer: 100% cotton. The catalog entry explicitly lists the material composition as '100% cotton', meaning the entire shirt is made from this natural fiber.","incorrect":[{"choice":"50 % cotton, 50% polyester","category":"incorrect material blend","reason":"This choice describes a blended fabric, but the catalog entry specifies that the shirt is made of 100% cotton, not a mix."},"",{"choice":"100% polyester","category":"incorrect fabric type","reason":"Polyester is a synthetic material. The catalog confirms the item is made from cotton, a natural fiber, so this is inaccurate."},{"choice":"100% silk","category":"incorrect fabric type","reason":"Silk is a different type of fabric entirely. The text clearly identifies the material as cotton."}]},"studyAid":{"definition":"Reading for information involves scanning a text for specific details like numbers, names, or materials to answer 'what', 'who', or 'where' questions.","example":"Question: 'What color is the jacket?' Text: 'Available in blue or green.' Answer: Blue or green.","strategyClue":"Highlight the specific keyword in the question, such as 'material,' then look for that keyword or its synonyms in the text to locate the correct detail.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-4_Informational Text.pdf","sourceQuestionNumber":5,"sourceCategory":"informational-text","sourceGrade":3,"sequence":191,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0192","version":3,"contentHash":"sha256:572b46be0e6c362cef57fcf5b62c86d9d268ff0c90237f3c13e899a2ab0a8032","question":"Read the passage. Plants need nutrients to make their food and get energy. Some plants that grow in poor soil get the nutrients they need by “eating” animals. A sweet -smelling liquid attracts insects to a pitcher plant. Once an insect enters the tube-shaped leaf of the plant, hairs that point downward stop it from leaving. The insect falls into the pool of liquid inside the leaf. The liquid dissolves the insect, and the plant uses the nutrients. Why do plants eat animals or insects?","choices":["they are natural predators","they do not eat animals or insects","they need them to produce a sweet liquid that provides nutrients","they need the nutrients"],"correct":3,"explanation":{"correct":"Answer: they need the nutrients. The passage explicitly states that plants get the nutrients they need by eating insects, explaining that the plant later uses these nutrients to survive.","incorrect":[{"choice":"they are natural predators","category":"unsupported claim","reason":"While the plant catches the insect, the text explains the 'why' based on nutritional needs rather than the plant being a predator by nature."},{"choice":"they do not eat animals or insects","category":"factual contradiction","reason":"This contradicts the passage, which clearly describes how a pitcher plant traps and dissolves an insect to obtain nutrients."},{"choice":"they need them to produce a sweet liquid that provides nutrients","category":"misreading details","reason":"The passage says the liquid is used to attract the insect, not that the insect is needed to make the liquid."},""]},"studyAid":{"definition":"To find the main idea or reason in a text, look for cause-and-effect relationships where the author explains the purpose behind an action.","example":"Question: Why do bears sleep in winter? Answer: They sleep to conserve energy when food is hard to find.","strategyClue":"Search the text for the specific action mentioned in the question, then look at the words immediately surrounding it for a reason, such as 'to', 'because', or 'for'.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-4_Informational Text.pdf","sourceQuestionNumber":7,"sourceCategory":"informational-text","sourceGrade":3,"sequence":192,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0193","version":3,"contentHash":"sha256:88bb296502bb1da1b9e1f904fc19d51db31c5d3b6dca002854ccecd2f51c0c52","question":"Read the letter. The purpose of the letter is to:","choices":["t ell Amie what to bring to the party","invite Amie to the party","thank Amie for attending the party","tell Amie she’s sorry she missed her at school"],"correct":0,"explanation":{"correct":"Answer: tell Amie what to bring to the party. Look for the specific section of the letter that lists items like snacks or supplies, as this confirms the purpose is to provide instructions for the event.","incorrect":["",{"choice":"invite Amie to the party","category":"misreading the purpose","reason":"This choice assumes the party is yet to be invited, but the letter focuses on preparation details for a party that is already planned."},{"choice":"thank Amie for attending the party","category":"tense and content error","reason":"The letter focuses on planning for an upcoming event, not reflecting on a past event where Amie has already attended."},{"choice":"tell Amie she’s sorry she missed her at school","category":"misunderstanding the theme","reason":"While the letter might mention school, its primary goal is giving information about the party, not an apology regarding missed school time."}]},"studyAid":{"definition":"The purpose of a text is the main reason an author wrote it, often found by looking for the most important details or actions requested.","example":"A recipe's purpose is to teach how to cook; a grocery list's purpose is to remember items; an invitation's purpose is to ask someone to attend.","strategyClue":"Underline the key sentences in the letter that ask a question or give a command. Determine if those sentences are about inviting, thanking, or giving instructions.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":75,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Advanced-4_Informational Text.pdf","sourceQuestionNumber":8,"sourceCategory":"informational-text","sourceGrade":3,"sequence":193,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0194","version":3,"contentHash":"sha256:b65995fdd030dbe134366661b27345a66aa3e3930d4eb7a91a426e5527affba4","question":"Ryan likes to play ball. He likes his pet dog. His favorite toy is a truck. He is a little boy. What is he?","choices":["a boy","a dog","a girl","a ball"],"correct":0,"explanation":{"correct":"Answer: a boy. The text explicitly states, 'He is a little boy,' which directly identifies the person referred to in the passage.","incorrect":["",{"choice":"a dog","category":"incorrect identification","reason":"The text mentions he has a pet dog, but it clearly identifies Ryan himself as a boy, not the pet."},{"choice":"a girl","category":"incorrect gender identity","reason":"The pronoun 'He' is used throughout the passage, which indicates that Ryan is a boy, not a girl."},{"choice":"a ball","category":"inanimate object mismatch","reason":"A ball is an object Ryan likes to play with, not a description of who he is."}]},"studyAid":{"definition":"Reading comprehension means looking back at the text to find facts and details that answer your questions.","example":"Text: 'Sarah loves cats.' Question: 'What pet does Sarah love?' Answer: 'cats.'","strategyClue":"Scan the text for the specific subject mentioned in the question and look for the sentence where the author describes that person or object directly.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Basic-1_Informational Text.pdf","sourceQuestionNumber":7,"sourceCategory":"informational-text","sourceGrade":3,"sequence":194,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0195","version":3,"contentHash":"sha256:06d92ffe65dc40f8945a5ec24383be7c91a686196374ae7a12bf818dcf4eaee2","question":"Read the riddle and answer the question. I live in the water. I can swim. I have scales. I breathe through gills. What am I?","choices":["a dog","a whale","a house","a fish"],"correct":3,"explanation":{"correct":"Answer: a fish. A fish is the only choice that lives in water, possesses scales, and breathes using gills as described in the riddle.","incorrect":[{"choice":"a dog","category":"mammal traits mismatch","reason":"Dogs live on land and have fur, not scales. They also breathe air with lungs rather than using gills."},{"choice":"a whale","category":"respiratory system mismatch","reason":"While whales live in the water, they are mammals that breathe through blowholes with lungs. They do not have gills or scales like a fish."},{"choice":"a house","category":"inanimate object mismatch","reason":"A house is a building, not a living creature. It cannot swim, breathe, or have scales."},""]},"studyAid":{"definition":"Riddles describe the characteristics of a subject to help you identify it. To solve them, look for clues about where something lives, what it does, and how its body works.","example":"Clue: 'I have feathers and fly.' Answer: A bird. Clue: 'I am made of metal and help you write.' Answer: A pen.","strategyClue":"Create a checklist based on each sentence in the riddle and test each potential answer against every item on your list until only one remains.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"sentence-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Basic-2_Informational Text.pdf","sourceQuestionNumber":3,"sourceCategory":"informational-text","sourceGrade":3,"sequence":195,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0196","version":3,"contentHash":"sha256:8dee315208c6c29634f2fd3593d5b6c063d1ab5453e1a533f258e85e18f36975","question":"Read the story and answer the question. You cando many things at the beach. Whenthe tide is out, you can fill your pail full of sea water. You can build sand castles in the sand on the beach. You can jump in the waves and swim. What is this story mostly about?","choices":["Whenthe tide is out, you can fill your pail.","You can build sand castles.","You can jump in the waves and swim.","There are many things to do at the beach."],"correct":3,"explanation":{"correct":"Answer: There are many things to do at the beach. This sentence captures the main idea because it summarizes all the individual activities mentioned in the text, such as filling a pail, building sand castles, and swimming.","incorrect":[{"choice":"Whenthe tide is out, you can fill your pail.","category":"too narrow focus","reason":"This is a supporting detail, not the main idea. It only covers one small part of the paragraph rather than the overall theme."},{"choice":"You can build sand castles.","category":"too narrow focus","reason":"This describes just one specific activity. A main idea should summarize the whole story, not just one sentence from it."},{"choice":"You can jump in the waves and swim.","category":"too narrow focus","reason":"While this is a fun activity mentioned in the text, it represents only one action rather than the entire list of things you can do at the beach."},""]},"studyAid":{"definition":"The main idea is the 'big picture' message of a story. It tells you what the entire text is mostly about, not just one small detail.","example":"If a story lists apple pie, carrot cake, and chocolate brownies, the main idea is 'delicious desserts,' not just 'apple pie.'","strategyClue":"Look at each sentence and ask yourself, 'Does this cover everything mentioned in the story?' If it only describes one part, it is a detail, not the main idea.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Basic-3_Informational Text.pdf","sourceQuestionNumber":4,"sourceCategory":"informational-text","sourceGrade":3,"sequence":196,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0197","version":3,"contentHash":"sha256:2a431d38f65f562b5df28b7a67e89bb405318a9a74c1dc0cbe8717fa27c876f7","question":"Read the titles of the books. Which book tells you something about plants?","choices":["Going to the Fair","The Lady with an Alligator","Pumpkin, Pumpkin","My Friend, Ben"],"correct":2,"explanation":{"correct":"Answer: Pumpkin, Pumpkin. A pumpkin is a type of plant, so a book with this title is most likely to be about how plants grow or live.","incorrect":[{"choice":"Going to the Fair","category":"Topic irrelevance","reason":"Going to a fair is usually about people, rides, or games, not about the biology or growth cycle of plants."},{"choice":"The Lady with an Alligator","category":"Topic irrelevance","reason":"This title focuses on a person and an animal, which does not relate to the study or life cycle of plants."},"",{"choice":"My Friend, Ben","category":"Topic irrelevance","reason":"This title suggests a story about a personal friendship with another person, rather than information regarding plant life."}]},"studyAid":{"definition":"To find the main topic of a book, look at the title for clues that describe the subject matter.","example":"Title 'The Life of a Frog' is about amphibians; Title 'Gardening Basics' is about plants.","strategyClue":"Think about what each noun in the title represents. If the word refers to something that grows from a seed or lives in a garden, that is your clue.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Basic-3_Informational Text.pdf","sourceQuestionNumber":5,"sourceCategory":"informational-text","sourceGrade":3,"sequence":197,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0198","version":3,"contentHash":"sha256:69a0b106be463ce47398e1ffa9c29476d79a48ac69e36f16b3c6ab90c8b8b967","question":"Read the passage and answer the question. Little Jon looked out of the window, and let his mind rove over the greening valley in the distance. Suddenly he began to hum a little song about valleys. The humming changed to singing words. He wondered where he had heard it. Little Jon began to sing when:","choices":["he didn’t know the words.","he saw the green grass.","he was singing with friends.","he looked out the window."],"correct":3,"explanation":{"correct":"Answer: he looked out the window. The passage describes Little Jon looking out the window, followed by his mind roving, and then beginning to hum and sing. Therefore, his singing follows his observation of the window view.","incorrect":[{"choice":"he didn’t know the words.","category":"not in text","reason":"The passage says he was 'singing words,' but it does not state that he did not know them. This choice assumes information that is not mentioned in the text."},{"choice":"he saw the green grass.","category":"misinterpretation of text","reason":"While the passage mentions a 'greening valley,' it does not specifically mention him seeing green grass. Always look for the exact actions described in the story."},{"choice":"he was singing with friends.","category":"contrary to text","reason":"The passage describes Little Jon alone looking out the window, with no mention of friends or other people being present during his singing."},""]},"studyAid":{"definition":"Reading comprehension means finding the specific details in a text to understand what happened and when it happened.","example":"If the story says 'The cat jumped after it saw the mouse,' you know the cat jumped because of the mouse, not because it was hungry.","strategyClue":"Trace the timeline of the character's actions from the beginning of the paragraph to the end, identifying the specific event that happens immediately before the character starts the main action in the question.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"passage-context","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Basic-3_Informational Text.pdf","sourceQuestionNumber":8,"sourceCategory":"informational-text","sourceGrade":3,"sequence":198,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0199","version":3,"contentHash":"sha256:e73e3d5b8324cb9e05ccb42efdb01e16dea1d3d823c63e2d71e32541c5cdf376","question":"Which word is not like the others?","choices":["pig","zebra","rose","rabbit"],"correct":2,"explanation":{"correct":"Answer: rose. A rose is a type of flower, while the other choices are all types of animals.","incorrect":[{"choice":"pig","category":"animal category","reason":"A pig is an animal, so it fits with the group of other animals like the zebra and the rabbit."},{"choice":"zebra","category":"animal category","reason":"A zebra is a wild animal; it belongs in the animal group rather than being the odd one out."},"",{"choice":"rabbit","category":"animal category","reason":"A rabbit is a small animal, so it shares the same category as the pig and the zebra."}]},"studyAid":{"definition":"To find the word that is not like the others, look for a common theme or category that most of the words share.","example":"Group: Apple, Banana, Orange (Fruit); Odd one out: Car. Group: Blue, Red, Green (Colors); Odd one out: Table.","strategyClue":"Label each item in the list. If three items share a specific group label (like 'animals' or 'colors') and one does not, you have found the outlier.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Basic-4_Informational Text.pdf","sourceQuestionNumber":1,"sourceCategory":"informational-text","sourceGrade":3,"sequence":199,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0200","version":4,"contentHash":"sha256:6d9b430a0b227fa4b20005d63dac359438a97c89b94d651f07881c87b2febc17","question":"Choose the missing word. It has two blades. You cut it. It is sharp. It is a _________.","choices":["p air of scissors","crayon","book","pen"],"correct":0,"explanation":{"correct":"Answer: pair of scissors. Scissors are a plural noun because they are made of two connected blades that work as one unit, which is why we refer to them as a 'pair of scissors'.","incorrect":["",{"choice":"crayon","category":"incorrect vocabulary object","reason":"A crayon is a tool for coloring, not cutting. It does not have two blades or a sharp edge meant for slicing paper."},{"choice":"book","category":"incorrect vocabulary object","reason":"A book contains pages for reading and does not have blades. It is meant for stories or information, not for cutting objects."},{"choice":"pen","category":"incorrect vocabulary object","reason":"A pen is a tool for writing with ink. It does not have two blades and is not used for cutting materials."}]},"studyAid":{"definition":"Some objects that consist of two identical parts joined together are always treated as a plural pair, even though we think of them as one single item.","example":"a pair of scissors, a pair of pants, a pair of eyeglasses","strategyClue":"Think about the function described in the sentence: identify the tool that specifically requires two blades to perform the action of cutting.","link":"https://www.readingrockets.org/topics/comprehension","linkText":"Reading Rockets-Comprehension"},"metadata":{"gradeLevels":[3],"difficultyByGrade":{"3":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"infer-and-support","languageDemand":"short-prompt","skills":["informational text","reading comprehension","reading","grade 3"],"feedbackFocus":"use the passage, text feature, or story detail and compare each answer choice to the evidence","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reading-comprehension-text-evidence","sourceFile":"Basic-4_Informational Text.pdf","sourceQuestionNumber":5,"sourceCategory":"informational-text","sourceGrade":3,"sequence":200,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, with 15 exact-match questions for every supported grade and difficulty"}};
  const bank = window.QUESTION_BANK = window.QUESTION_BANK || {};
  const existing = bank["reading-comprehension-text-evidence"];
  if (existing && Array.isArray(existing.questions)) {
    const seen = new Set(existing.questions.map(question => question && question.id));
    chunkSet.questions.forEach(question => {
      if (!seen.has(question && question.id)) existing.questions.push(question);
    });
  } else {
    bank["reading-comprehension-text-evidence"] = chunkSet;
  }
})();
